'use client';

import * as React from 'react';
import { RadioGroup } from '@base-ui/react/radio-group';
import { Radio } from '@base-ui/react/radio';
import { SlidingIndicator } from '../../motion/indicator';
import './segmented.css';

/* ─────────────────────────────────────────────────────────
 * SEGMENTED CONTROL (object sheet) on Base UI RadioGroup
 *
 *   rest      a well track; segments in ink2, the selected one a raised thumb in ink
 *   hover     the label turns ink (settle)
 *   select    the thumb glides to the new segment on the part spring (a track with
 *             ends, so it may overshoot against the stop); labels recolour on settle
 *   focus     a 1.5 ring with no offset (a dense strip); arrows move the selection
 *   disabled  40 %
 * First paint and resizing place the thumb without motion. Reduce Motion: it moves at once.
 * ───────────────────────────────────────────────────────── */

export interface SegmentedOption<V extends string = string> {
  value: V;
  label: React.ReactNode;
  /** A leading glyph at the size the height gives (12 in 24, 14 in 28). */
  icon?: React.ReactNode;
  disabled?: boolean;
}

export interface SegmentedProps<V extends string = string> {
  options: SegmentedOption<V>[];
  value?: V;
  defaultValue?: V;
  onValueChange?: (value: V) => void;
  /** compact is 24 tall (in a lens bar, a strip), regular 28. */
  size?: 'compact' | 'regular';
  disabled?: boolean;
  'aria-label': string;
  className?: string;
}

/** A pill of pills: one of a few views or modes, always visible. */
export function Segmented<V extends string = string>({ options, value, defaultValue, onValueChange, size = 'regular', disabled, className, ...props }: SegmentedProps<V>) {
  return (
    <RadioGroup
      value={value}
      defaultValue={defaultValue}
      onValueChange={(v) => onValueChange?.(v as V)}
      disabled={disabled}
      aria-label={props['aria-label']}
      data-size={size}
      className={className ? `mu-segmented ${className}` : 'mu-segmented'}
    >
      <SlidingIndicator className="mu-segmented-thumb" />
      {options.map((o) => (
        <Radio.Root key={o.value} value={o.value} disabled={o.disabled} className="mu-segment">
          {o.icon}
          {o.label}
        </Radio.Root>
      ))}
    </RadioGroup>
  );
}

@import "../tokens.css";

/* Segmented control: a pill of pills on Base UI RadioGroup. Its look is the segmented recipe (--mu-r-segmented-*). */
.mu-segmented {
  position: relative;
  display: inline-flex;
  padding: var(--mu-r-segmented-self-pad);
  border-radius: var(--mu-radius-pill);
  background: var(--mu-r-segmented-self-background);
  box-shadow: var(--mu-r-segmented-self-shadow);
}
.mu-segment {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: var(--mu-r-segmented-self-gap);
  height: var(--mu-r-segmented-segment-height-regular);
  padding: var(--mu-zero) var(--mu-r-segmented-segment-pad-x);
  margin: var(--mu-zero);
  border: var(--mu-zero);
  border-radius: var(--mu-radius-pill);
  background: transparent;
  white-space: nowrap;
  font: var(--mu-r-segmented-segment-font);
  letter-spacing: var(--mu-r-segmented-segment-tracking);
  color: var(--mu-r-segmented-segment-ink);
  cursor: pointer;
  transition: color var(--mu-r-segmented-segment-fade);
  -webkit-tap-highlight-color: transparent;
}
.mu-segmented[data-size="compact"] .mu-segment { height: var(--mu-r-segmented-segment-height); }
.mu-segment:hover, .mu-segment[data-checked] { color: var(--mu-r-segmented-segment-ink-on); }
.mu-segment:focus-visible { outline: var(--mu-r-segmented-segment-focus-width) solid var(--mu-focus); outline-offset: var(--mu-zero); }
.mu-segment[data-disabled], .mu-segmented[data-disabled] { opacity: var(--mu-r-segmented-segment-disabled); }
.mu-segment[data-disabled] { cursor: default; }
/* The thumb: a raised cap that glides on the part spring (SlidingIndicator). */
.mu-segmented > .mu-segmented-thumb {
  border-radius: var(--mu-radius-pill);
  background: var(--mu-r-segmented-thumb-background);
  box-shadow: var(--mu-r-segmented-thumb-shadow);
}
